"""Config loading and LLM client construction for the eval suite."""

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, Optional

from pydantic import BaseModel, ConfigDict, Field
from pydantic import ValidationError as PydanticValidationError

from rasa.shared.constants import PROVIDER_CONFIG_KEY
from rasa.shared.data import YAML_FILE_EXTENSIONS
from rasa.shared.exceptions import InvalidPromptTemplateException, RasaException
from rasa.shared.providers.llm.llm_client import LLMClient
from rasa.shared.utils.llm import get_prompt_template, llm_factory
from rasa.shared.utils.yaml import read_yaml_file

_CONFTEST_PATHS = [Path("eval") / f"conftest{ext}" for ext in YAML_FILE_EXTENSIONS]


class EvalConfigError(RasaException):
    """Raised when eval conftest file is absent or incorrectly configured."""


class LLMConfig(BaseModel):
    """LLM provider and model configuration."""

    model_config = ConfigDict(extra="allow")

    provider: str = Field(..., description="LLM provider (e.g. openai, anthropic)")
    model: str = Field(..., description="Model name or deployment identifier")


class SimulationConfig(BaseModel):
    """LLM configuration for the simulation role."""

    llm: LLMConfig
    simulated_user_prompt: Optional[str] = None


class EvaluationConfig(BaseModel):
    """LLM configuration for the evaluation role and optional prompt overrides."""

    llm: LLMConfig
    criteria_judge_prompt: Optional[str] = None
    metrics_judge_prompt: Optional[str] = None


class ConftestConfig(BaseModel):
    """Parsed and validated representation of eval conftest file."""

    simulation: SimulationConfig
    evaluation: EvaluationConfig


def load_conftest(project_path: Path) -> ConftestConfig:
    """Load and validate eval conftest file from the project root.

    Args:
        project_path: Root directory of the Rasa project.

    Returns:
        Validated ConftestConfig.

    Raises:
        EvalConfigError: If the file is missing, or incorrectly formatted.
    """
    conftest_path = next(
        (project_path / p for p in _CONFTEST_PATHS if (project_path / p).exists()),
        None,
    )
    if conftest_path is None:
        raise EvalConfigError(
            f"'{project_path / _CONFTEST_PATHS[0]}' not found. "
            "Create eval/conftest.yml (or conftest.yaml) "
            "with 'simulation.llm' and 'evaluation.llm' blocks."
        )

    try:
        raw: Any = read_yaml_file(conftest_path, skip_cache=True)
    except Exception as exc:
        raise EvalConfigError(f"Could not parse '{conftest_path}': {exc}") from exc

    if not isinstance(raw, dict):
        raise EvalConfigError(
            f"'{conftest_path}' must be a YAML mapping, got {type(raw).__name__}."
        )

    try:
        return ConftestConfig.model_validate(raw)
    except PydanticValidationError as exc:
        raise EvalConfigError(
            f"Invalid configuration in '{conftest_path}':\n{exc}"
        ) from exc


def build_llm_client(llm_config: LLMConfig) -> LLMClient:
    """Build an LLMClient from an LLMConfig.

    Args:
        llm_config: LLM configuration block from conftest.

    Returns:
        Initialised LLMClient.

    Raises:
        EvalConfigError: If the configuration is invalid or the client cannot be built.
    """
    config_dict: Dict[str, Any] = llm_config.model_dump()
    # llm_factory requires provider in default_config; config_dict alone is
    # insufficient because llm_factory looks up the provider key there first.
    default_config = {PROVIDER_CONFIG_KEY: llm_config.provider}

    try:
        return llm_factory(config_dict, default_config)
    except Exception as exc:
        raise EvalConfigError(
            f"Failed to build LLM client "
            f"(provider='{llm_config.provider}', model='{llm_config.model}'): {exc}"
        ) from exc


def load_prompt_template(project_path: Path, template_path: str) -> str:
    """Load a Jinja2 prompt template from the project directory.

    Args:
        project_path: Root directory of the Rasa project.
        template_path: Path to the template file, relative to the project root.

    Returns:
        Template file contents as a string.

    Raises:
        EvalConfigError: If the template file does not exist, cannot be read,
            or is empty.
    """
    full_path = (project_path / template_path).resolve()
    if not full_path.is_relative_to(project_path.resolve()):
        raise EvalConfigError(
            f"Prompt template path '{template_path}' escapes the project directory."
        )

    try:
        content = get_prompt_template(str(full_path), default_prompt_template="")
    except InvalidPromptTemplateException as exc:
        raise EvalConfigError(
            f"Prompt template not found or unreadable: '{template_path}'. "
            f"Check the path in eval/conftest.yml."
        ) from exc

    if not content.strip():
        raise EvalConfigError(f"Prompt template '{template_path}' is empty.")

    return content
